/*
 Problem: 1386. Cinema Seat Allocation
 Language: cpp
 Runtime: 20 ms (69.30%)
 Memory: 59.2 MB (60.27%)
 Tags: Array, Hash Table, Greedy, Bit Manipulation
*/
class Solution {
public:
    int maxNumberOfFamilies(int n, vector<vector<int>>& reservedSeats) {
        unordered_map<int, int> mp;

        for (auto& seat : reservedSeats) {
            if (seat[1] >= 2 && seat[1] <= 9)
                mp[seat[0]] |= 1 << seat[1];
        }

        const int L = (1 << 2) | (1 << 3) | (1 << 4) | (1 << 5);
        const int M = (1 << 4) | (1 << 5) | (1 << 6) | (1 << 7);
        const int R = (1 << 6) | (1 << 7) | (1 << 8) | (1 << 9);

        int ans = (n - mp.size()) * 2;

        for (auto& [row, mask] : mp) {
            bool l = !(mask & L);
            bool m = !(mask & M);
            bool r = !(mask & R);

            if (l && r) ans += 2;
            else if (l || m || r) ans++;
        }

        return ans;
    }
};
